def przenies_rekomendacje(apps, schema_editor):
    zrodla = apps.get_model("teraz", "Zrodlo").objects.using(schema_editor.connection.alias)
    rejestr = import_module("teraz.migrations.0004_rejestr_zrodel")
    for slug, *_dane, tryb, _pro, _atrybucja, podstawa in rejestr.ZRODLA:
        rekomendacja = f"Z0-PRAWNIK §3. Rekomendowany tryb docelowy: {tryb}. {podstawa}"
        zrodlo = zrodla.filter(slug=slug)
        zrodlo.update(podstawa_rekomendowana=rekomendacja, rekomendowany_tryb=tryb)
        zrodlo.filter(podstawa_prawna=rekomendacja, tryb="publiczny").update(
            tryb="wylaczony" if tryb == "wylaczony" else "wewnetrzny", tryb_zmienil=None, tryb_zmiana_at=None,
        )
        zrodlo.filter(podstawa_prawna=rekomendacja).update(podstawa_prawna="")
    bez_wyjatku = zrodla.filter(tryb="publiczny").filter(
        models.Q(wyjatek_podpisal__isnull=True) | models.Q(wyjatek_decyzja=""),
    )
    for tryb in ("wewnetrzny", "wylaczony"):
        bez_wyjatku.filter(rekomendowany_tryb=tryb).update(tryb=tryb, tryb_zmienil=None, tryb_zmiana_at=None)


def uporzadkuj_wpisy(apps, schema_editor):
    alias = schema_editor.connection.alias
    wpisy = apps.get_model("teraz", "Wpis").objects.using(alias)
    hydro = wpisy.filter(zrodlo__slug="imgw_hydro", zewnetrzny_id__startswith="stan:")
    gios = wpisy.filter(zrodlo__slug="gios")
    hydro.exclude(wersje=[]).update(wersje=[])
    gios.exclude(wersje=[]).update(wersje=[])

    stan_gios = (apps.get_model("teraz", "Zrodlo").objects.using(alias).filter(slug="gios")
                 .values_list("stan_adaptera", flat=True).first() or {})
    indeksy = stan_gios.get("indeksy", {})
    stacje = set(indeksy) | set(stan_gios.get("stacje", {}))
    aktualne = {}
    for wpis in gios.filter(usunieto_at__isnull=True).order_by("-opublikowano_at", "-pk").iterator():
        ident, separator, _ = wpis.zewnetrzny_id.partition(":")
        if not ident.isdecimal() or not separator:
            continue
        if ident not in aktualne:
            aktualne[ident] = wpis
        stacje.add(ident)
    odciski_stacji = {
        sha256(f"https://api.gios.gov.pl/pjp-api/v1/rest/aqindex/getIndex/{ident}".encode()).hexdigest(): ident
        for ident in stacje
    }
    usuniete_stacje = set()
    for wpis in gios.filter(usunieto_at__isnull=False).select_related("pobranie").iterator():
        ident = odciski_stacji.get(wpis.pobranie.odcisk_adresu)
        if ident:
            usuniete_stacje.add(ident)
            wpis.hash_zewnetrznego_id = sha256(f"indeks:{ident}".encode()).hexdigest()
            wpis.save(update_fields=["hash_zewnetrznego_id"])
    for ident, wpis in aktualne.items():
        przestarzale = gios.filter(zewnetrzny_id__startswith=f"{ident}:")
        if ident in usuniete_stacje:
            przestarzale.delete()
            continue
        przestarzale.exclude(pk=wpis.pk).delete()
        wpis.zewnetrzny_id = f"indeks:{ident}"
        if ident in indeksy:
            czas, kod = indeksy[ident]
            wpis.opublikowano_at = datetime.fromisoformat(czas)
            wpis.pomiar_aktywny = kod in (4, 5)
            nazwa = stan_gios.get("stacje", {}).get(ident, {}).get("nazwa", wpis.miejsce)
            opis = {4: "zły", 5: "bardzo zły"}.get(kod, str(kod))
            wpis.tytul = f"Indeks jakości powietrza: {opis} ({nazwa})"
        wpis.hash_wersji = ""
        wpis.save(update_fields=["zewnetrzny_id", "pomiar_aktywny", "opublikowano_at", "tytul", "hash_wersji"])

    # Historyczne dane RCB mogą zawierać w polu miejsca pełny adres zamiast nazwy jednostki.
    rcb = wpisy.filter(zrodlo__slug="rcb", usunieto_at__isnull=True)
    for wpis in rcb.iterator():
        pola = {"miejsce": "", "hash_wersji": ""}
        if wpis.wersje:
            pola["wersje"] = [{**wersja, "miejsce": ""} for wersja in wpis.wersje[-20:]]
        stary_id = re.fullmatch(r"(.+):aktualizacja:(\d\d:\d\d|bez-godziny):\d+", wpis.zewnetrzny_id)
        if stary_id and wpis.tresc:
            skrot = sha256(f"{stary_id[1]}:{stary_id[2]}:{wpis.tresc}".encode()).hexdigest()
            nowy_id = f"rcb:aktualizacja:{skrot}"
            if not rcb.filter(zewnetrzny_id=nowy_id).exists():
                pola["zewnetrzny_id"] = nowy_id
        rcb.filter(pk=wpis.pk).update(**pola)

    pozostale = wpisy.exclude(zrodlo__slug__in=("rcb", "gios")).exclude(wersje=[])
    for wpis in pozostale.only("wersje").iterator():
        if len(wpis.wersje) > 20:
            wpis.wersje = wpis.wersje[-20:]
            wpis.save(update_fields=["wersje"])


